#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
verify_shape.py —— 审查"画面的形状"，而不只是"有没有亮 / 有没有变"

为什么需要它（2026-11-26 客户两次退回）：
  * `Sunrise`(104)：平均亮度 41→175 看起来"有效果"，但亮区恒在中点 —— 客户说"太阳固定在一个区域"
  * 分层 Sunrise + Meteor：更糟 —— 整条静态亮场(86% 宽度、波动≈0) + 5% 灯珠的小点在转圈
    —— 客户说"一个大太阳不动，还有个小黄点在转圈"
  两个问题 `verify_live.py`（覆盖率/色差）和 `verify_motion.py`（质心位移）都能"通过"，
  因为它们都不看**亮区的形状与边界位置**。

判据（针对"推进类"效果，比如日出/擦除/填充）：
  1. 亮区**右边界**随时间单调增长（≥ 屏宽的 25%）⇒ 边界真的在走
  2. 亮区**宽度**必须有变化（<5% 变化 = 整条同亮同灭，没有推进）
  3. 不允许出现"亮但完全不波动"的静态亮块（>60% 亮度且段内波动≈0）

用法：
    python3 scripts/verify_shape.py --ip 192.168.2.58 --seconds 30
    python3 scripts/verify_shape.py --ip 192.168.2.63 --seconds 30 --samples 6 --json

退出码：0 = 形状符合"推进"；1 = 不符合。
"""
from __future__ import annotations

import argparse
import json
import sys
import time

import websocket


def shot(ip: str, sec: float = 1.2):
    ws = websocket.create_connection(f"ws://{ip}/ws", timeout=5)
    ws.send('{"lv":true}')
    ws.settimeout(0.05)
    fr, t0 = [], time.time()
    while time.time() - t0 < sec:
        try:
            d = ws.recv()
        except Exception:
            continue
        if isinstance(d, (bytes, bytearray)) and len(d) > 5 and d[0] == ord("L") and d[1] == 1:
            fr.append(bytes(d[2:]))
    try:
        ws.send('{"lv":false}')
        ws.close()
    except Exception:
        pass
    if not fr:
        return None
    n = len(fr[-1]) // 3
    luma = [sum((f[i * 3] + f[i * 3 + 1] + f[i * 3 + 2]) / 3 for f in fr) / len(fr) for i in range(n)]
    peak = max(luma) or 1.0
    bright = [i for i, v in enumerate(luma) if v > peak * 0.6]
    # 亮区内部的波动（判断是不是一块"死"的亮场）
    var = 0.0
    for i in bright or [0]:
        vals = [(f[i * 3] + f[i * 3 + 1] + f[i * 3 + 2]) / 3 for f in fr]
        m = sum(vals) / len(vals)
        var = max(var, (sum((v - m) ** 2 for v in vals) / len(vals)) ** 0.5)
    return {
        "n": n,
        "width": len(bright) / n,
        "left": bright[0] if bright else -1,
        "right": bright[-1] if bright else -1,
        "peak": peak,
        "peak_pos": luma.index(peak) / (n - 1),
        "var": var,
        "profile": [round(v / peak, 1) for v in luma[:: max(1, n // 20)]],
    }


def main() -> int:
    ap = argparse.ArgumentParser(description="审查画面形状：亮界是否在推进、有没有静态亮块")
    ap.add_argument("--ip", required=True)
    ap.add_argument("--seconds", type=float, default=30.0)
    ap.add_argument("--samples", type=int, default=6)
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args()

    gap = max(0.2, args.seconds / max(1, args.samples - 1))
    runs = []
    for k in range(args.samples):
        if k:
            time.sleep(gap)
        s = shot(args.ip)
        if s:
            runs.append(s)
    if len(runs) < 2:
        print("取不到足够的帧", file=sys.stderr)
        return 1

    widths = [round(r["width"], 2) for r in runs]
    rights = [r["right"] for r in runs]
    n = runs[0]["n"]
    edge_growth = (max(rights) - min(rights)) / n
    width_span = max(widths) - min(widths)
    max_var = max(r["var"] for r in runs)
    # 软渐变里"亮区边界"会被阈值钝化，峰值的位移才可靠
    peaks = [r["peak_pos"] for r in runs]
    peak_drift = max(peaks) - min(peaks)
    advancing = edge_growth >= 0.25 or peak_drift >= 0.25
    varies = width_span >= 0.05
    static_block = max_var < 3 and max(widths) > 0.5     # 大面积亮且完全不波动

    if args.json:
        print(json.dumps({
            "ip": args.ip, "leds": n, "widths": widths, "right_edges": rights,
            "edge_growth": round(edge_growth, 2), "width_span": round(width_span, 2),
            "peak_drift": round(peak_drift, 2),
            "max_variation": round(max_var, 1), "advancing": advancing,
            "width_varies": varies, "static_block": static_block,
        }, ensure_ascii=False, indent=2))
        return 0 if (advancing and varies and not static_block) else 1

    print(f"{args.ip}  {n} 颗  {len(runs)} 次采样 / {args.seconds:g}s")
    print(f"  宽度 {' → '.join(f'{w*100:.0f}%' for w in widths)}")
    print(f"  右边界 {' → '.join(str(r) for r in rights)}")
    print(f"  空间剖面（每格 = 1/20 屏宽，1.0 = 该帧峰值）")
    for k, r in enumerate(runs[:3]):
        print(f"    采样{k+1} " + "".join(" .:-=+*#%@"[min(9, int(v * 9))] for v in r["profile"]))
    print(f"  右边界增长 {edge_growth*100:.0f}% | 峰值漂移 {peak_drift*100:.0f}% | 宽度变化 {width_span*100:.0f}% | 亮区波动 {max_var:.1f}")
    problems = []
    if not advancing:
        problems.append("右边界没推进（亮区位置基本不变）")
    if not varies:
        problems.append("宽度几乎不变（整条同亮同灭，没有推进）")
    if static_block:
        problems.append("存在大面积静态亮块（亮但完全不波动）")
    print("  判定：" + ("形状合格（边界在推进）" if not problems else "不合格 —— " + "；".join(problems)))
    return 0 if not problems else 1


if __name__ == "__main__":
    sys.exit(main())
# AI: end
